css:
.print-format { font-family: Arial, sans-serif; font-size: 11px; }
.wht-copy { page-break-before: always; }
.wht-copy:first-child { page-break-before: auto; }
.wht-copy h2 { text-align: center; }
.wht-copy table { width: 100%; border-collapse: collapse; margin: 12px 0; }
.wht-copy th, .wht-copy td { border: 1px solid #333; padding: 6px !important; vertical-align: top; }
.wht-copy .amount { text-align: right; white-space: nowrap; }
.wht-copy .cancelled { color: #b00; font-size: 24px; text-align: center; }
.wht-copy .signature { margin-top: 30px; text-align: right; }

html:
{% set copies = [
    'Copy 1: For the income recipient to attach to the tax return',
    'Copy 2: For the income recipient to retain as evidence',
    'Copy 3: For the withholding agent to attach to the tax return',
    'Copy 4: Book copy for the withholding agent to retain as evidence'
] %}
{% set supplier = frappe.get_doc("Supplier", doc.supplier) %}
{% set total_base = doc.withholding_tax_items | sum(attribute='tax_base') %}
{% set total_tax = doc.withholding_tax_items | sum(attribute='tax_amount') %}
{% macro address(address_name) %}
    {% set a = frappe.get_doc("Address", address_name) %}
    {% for part in [a.address_line1, a.address_line2, a.city, a.county, a.state, a.pincode] if part %}
        {{ part | e }}{% if not loop.last %}, {% endif %}
    {% endfor %}
{% endmacro %}
{% macro certificate_date(value) %}
    {% if value %}
        {% set date = value | str %}
        {{ date[8:10] }}/{{ date[5:7] }}/{{ (date[0:4] | int) + 543 }} B.E.
    {% else %}-{% endif %}
{% endmacro %}
{% for copy in copies %}
<section class="wht-copy">
    <p>{{ copy }}</p>
    <h2>Withholding Tax Certificate</h2>
    {% if doc.docstatus == 2 %}<p class="cancelled">Cancelled</p>{% endif %}
    <p><strong>Certificate No.:</strong> {{ doc.name | e }}</p>
    <p><strong>Reference Voucher:</strong> {{ doc.voucher_no | e }}</p>
    {% if doc.amended_from %}<p><strong>Replaces Certificate No.:</strong> {{ doc.amended_from | e }}</p>{% endif %}
    <p><strong>Date:</strong> {{ certificate_date(doc.date) }}</p>
    <table>
        <tr><th>Withholding Agent</th><th>Income Recipient</th></tr>
        <tr>
            <td>
                <strong>Name:</strong> {{ doc.company | e }}<br>
                <strong>Tax ID:</strong> {{ (doc.company_tax_id or '-') | e }}<br>
                <strong>Address:</strong> {{ address(doc.company_address) }}
            </td>
            <td>
                <strong>Name:</strong> {{ supplier.supplier_name | e }}<br>
                {% if doc.is_agent and doc.withholding_agent_for_name %}
                    <strong>Acting on behalf of:</strong> {{ doc.withholding_agent_for_name | e }}<br>
                {% endif %}
                <strong>Tax ID:</strong> {{ (supplier.tax_id or '-') | e }}<br>
                <strong>Address:</strong> {{ address(doc.supplier_address) }}
            </td>
        </tr>
    </table>
    <p><strong>Income Tax Form:</strong>
        {% for form in ['PND1', 'PND3', 'PND3a', 'PND53'] %}
            [{{ 'X' if doc.income_tax_form == form else ' ' }}] {{ form }} &nbsp;
        {% endfor %}
    </p>
    <table>
        <thead><tr>
            <th>Type of Income</th><th>Description</th><th>Payment Date</th>
            <th>Tax Base (THB)</th><th>Tax Rate (%)</th><th>Tax Withheld (THB)</th>
        </tr></thead>
        <tbody>
            {% for item in doc.withholding_tax_items | selectattr('type_of_income') %}
            <tr>
                <td>{{ item.type_of_income | e }}</td>
                <td>{{ (item.description or '') | e }}</td>
                <td>{{ certificate_date(doc.date) }}</td>
                <td class="amount">{{ "{:,.2f}".format(item.tax_base) }}</td>
                <td class="amount">{{ "{:,.2f}".format(item.tax_rate or 0) }}</td>
                <td class="amount">{{ "{:,.2f}".format(item.tax_amount) }}</td>
            </tr>
            {% endfor %}
        </tbody>
        <tfoot><tr>
            <th colspan="3">Total</th>
            <th class="amount">{{ "{:,.2f}".format(total_base) }}</th>
            <th></th><th class="amount">{{ "{:,.2f}".format(total_tax) }}</th>
        </tr></tfoot>
    </table>
    <p><strong>Tax Withheld in Words:</strong> {{ amount_to_text(total_tax, currency='THB', lang='en') | e }}</p>
    <p><strong>Tax Payer:</strong>
        {% for payer in ['Withholding', 'Paid One Time', 'Paid Continuously'] %}
            [{{ 'X' if doc.tax_payer == payer else ' ' }}] {{ payer }} &nbsp;
        {% endfor %}
    </p>
    <div class="signature">
        <p><strong>Withholding Agent Signature:</strong> {{ frappe.get_fullname(doc.owner) | e }}</p>
        <p><strong>Date:</strong> {{ certificate_date(doc.date) }}</p>
    </div>
</section>
{% endfor %}
